insert into packages(id,service_id,name,strap,img,crew,price_2h,price_day,cost_2h,cost_day,items,sort) values ('live-one','live','1 camera','Club matches and single courts','/img/stadiumcam.jpg',1,2500,5000,1230,2580,'[{"t": "1 operator", "d": "Sets up, runs the camera, stream and scoreboard, packs down."}, {"t": "Sony Z200 broadcast camera", "d": "20x zoom, so it follows play from one spot."}, {"t": "YoloBox Ultra", "d": "Streams, records and runs the graphics, with 4G internet built in."}, {"t": "DJI Mic 3 wireless microphones", "d": "Ground sound, or a mic for a guest caller."}, {"t": "Live scoreboard", "d": "Score, clock, team names and logos on screen all match."}, {"t": "Your sponsor logo", "d": "On screen for the whole stream."}, {"t": "YouTube, Facebook and your website", "d": "All at the same time. No viewer limit."}, {"t": "Full recording", "d": "Download link within 24 hours."}, {"t": "Viewer report", "d": "Total and peak viewers, to show sponsors."}]'::jsonb,0),('live-three','live','3 cameras','Finals, tournaments and national events','/img/desk.jpg',2,5000,10000,2400,5000,'[{"t": "2 operators", "d": "One directs the stream, one runs cameras and graphics."}, {"t": "3 wireless 4K cameras", "d": "A wide, a close-up and a second angle, cut live."}, {"t": "YoloBox Extreme", "d": "Cuts the cameras, streams and records, with 4G internet built in."}, {"t": "Commentary desk", "d": "RODECaster mixer and 2 broadcast headsets."}, {"t": "Web graphics", "d": "Scores and results pulled from your competition software."}, {"t": "Live scoreboard", "d": "Score, clock, team names and logos on screen all match."}, {"t": "Your sponsor logo", "d": "On screen for the whole stream."}, {"t": "YouTube, Facebook and your website", "d": "All at the same time. No viewer limit."}, {"t": "Full recording and viewer report", "d": "Recording within 24 hours, plus total and peak viewers."}]'::jsonb,1),('video-video','video','Video','One videographer, filmed in 4K','/img/poolcam.jpg',1,2500,5000,1450,2900,'[{"t": "Pro videographer", "d": "Sports specialist, on site the whole booking."}, {"t": "4K camera", "d": "Cinema-quality footage you can crop and reuse."}, {"t": "Wireless microphones", "d": "Clear sound for speeches and interviews."}, {"t": "Stabilised shots", "d": "Smooth action from the sideline."}, {"t": "All your footage", "d": "Download link within 48 hours."}, {"t": "Yours to use", "d": "Post it anywhere, forever."}]'::jsonb,0),('photo-photo','photo','Photography','One photographer, edited photos','/img/flag.jpg',1,2500,5000,1450,2900,'[{"t": "Pro sports photographer", "d": "On site the whole booking."}, {"t": "Sports lenses", "d": "Fast action, frozen sharp."}, {"t": "Every photo edited", "d": "Colour and light, done by hand."}, {"t": "Online gallery", "d": "Link within 48 hours. Share it with the squad."}, {"t": "Full resolution", "d": "Download for print and social."}, {"t": "Yours to use", "d": "Post and print anywhere."}]'::jsonb,0),('pod-pod','pod','Podcasting','Full podcast set, crew and multi-camera recording','/img/pod.jpg',1,2500,4500,1210,2560,'[{"t": "3 cameras", "d": "Three angles in 4K, ready for YouTube."}, {"t": "Shure MV7+ microphones", "d": "Up to 4 hosts and guests."}, {"t": "Studio mixing", "d": "Clean, balanced sound for every voice."}, {"t": "Pro lighting", "d": "Everyone looks their best on camera."}, {"t": "Producer", "d": "Sets up, runs the recording, packs down."}, {"t": "All files", "d": "Audio and video, download link within 48 hours."}]'::jsonb,0);
